<script>
	import { onMount } from 'svelte';
	import { Avatar, BadgeTile, Button, Card, EmptyState, Icon, Modal, PageHeader, PointsChip, StatTile, StatusBadge, TierProgress, ICONS } from '$lib/components';
	import { AMBANG_FITUR_PUBLIK } from '$lib/domain/constants/tier-table.js';
	import { ESG_ELIGIBLE_ACTIVITIES, ESG_PILLARS } from '$lib/domain/constants/esg-taxonomy.js';
	import { CONSENT_TYPE_META, ConsentType } from '$lib/domain/value-objects/ConsentRecord.js';
	import { gamification } from '$lib/stores/gamification.svelte.js';
	import { awardeeProfile } from '$lib/stores/profile.svelte.js';
	import { session } from '$lib/stores/session.svelte.js';
	import { toast } from '$lib/stores/toast.svelte.js';
	import { formatAngka, formatTanggal, frasaHitung } from '$lib/utils/format.js';

	const OPTIONAL_CONSENTS = Object.values(ConsentType).filter((type) => type !== ConsentType.PENGOLAHAN_DATA_INTERNAL);
	const WARNA_RISIKO = { RENDAH:'green', SEDANG:'amber', TINGGI:'red' };
	const awardee = $derived(session.awardee);
	const data = $derived(awardeeProfile.data);
	const profil = $derived(data?.profile ?? null);
	const statistik = $derived(data?.statistics ?? { total:0, processing:0, published:0, totalViews:0 });
	const produk = $derived(data?.products ?? []);
	const consentHistory = $derived(data?.consents?.history ?? []);
	const consentEffective = $derived(data?.consents?.effective ?? {});
	const lencanaTerkumpul = $derived(gamification.badges.filter((item) => item.unlocked));
	const ambangFiturPublik = $derived(gamification.tiers.find((tier) => tier.level === 'FEATURED_CANDIDATE')?.threshold ?? AMBANG_FITUR_PUBLIK);
	const poinFiturPublikTerpenuhi = $derived(gamification.points >= ambangFiturPublik);

	let editorProfilTerbuka=$state(false), consentDikonfirmasi=$state(null), sedangConsent=$state('');
	let editorProdukTerbuka=$state(false), produkDisunting=$state(null), berkasAvatar=$state(null), berkasProduk=$state(null);
	let formulirProfil=$state({}), formulirProduk=$state({name:'',category:'',description:''});

	onMount(async()=>{try{await awardeeProfile.load();}catch(error){toast.error('Profil gagal dimuat',error.message);}});

	const ringkasanEsg=$derived.by(()=>{const counts=new Map(ESG_PILLARS.map(item=>[item.pillar,0]));let total=0;for(const entry of gamification.ledger){if(!entry.isAwarded)continue;const mapping=ESG_ELIGIBLE_ACTIVITIES[entry.activityType];if(!mapping)continue;counts.set(mapping.pillar,(counts.get(mapping.pillar)||0)+1);total++;}return{total,rows:ESG_PILLARS.map(item=>({...item,count:counts.get(item.pillar)||0}))};});

	function bukaEditorProfil(){if(!profil)return;formulirProfil={whatsapp:profil.whatsapp||'',city:profil.city||'',occupation:profil.occupation||'',bio:profil.bio||'',skills:(profil.skills||[]).join(', '),openToMentoring:Boolean(profil.openToMentoring),profileVisibility:profil.profileVisibility||'DIRECTORY',businessName:profil.businessName||'',businessSector:profil.businessSector||'',businessCity:profil.businessCity||'',businessDescription:profil.businessDescription||'',businessContact:profil.businessContact||'',businessEmployees:profil.businessEmployees||0,businessGrowthPercent:profil.businessGrowthPercent||0};berkasAvatar=null;editorProfilTerbuka=true;}
	async function simpanProfil(){const body=new FormData();for(const[key,value]of Object.entries(formulirProfil))body.set(key,key==='skills'?JSON.stringify(String(value).split(',').map(item=>item.trim()).filter(Boolean)):String(value));if(berkasAvatar)body.set('avatar',berkasAvatar);try{await awardeeProfile.update(body);await session.refresh();editorProfilTerbuka=false;toast.success('Profil diperbarui','Perubahan tersimpan di PocketBase dan dicatat pada audit profil.');}catch(error){toast.error('Profil gagal disimpan',error.message);}}

	async function aktifkanConsent(type){sedangConsent=type;try{await awardeeProfile.grant(type);await session.refresh();toast.success('Persetujuan diaktifkan',`Versi kebijakan aktif untuk ${CONSENT_TYPE_META[type].label} sudah tercatat.`);}catch(error){toast.error('Persetujuan gagal diaktifkan',error.message);}finally{sedangConsent='';}}
	async function cabutConsent(){const type=consentDikonfirmasi;if(!type)return;sedangConsent=type;try{const result=await awardeeProfile.revoke(type);await session.refresh();consentDikonfirmasi=null;const detail=type===ConsentType.PUBLIKASI_CERITA?`${frasaHitung(result.withdrawn||0,'Cerita')} ditarik dan ${frasaHitung(result.blocked||0,'naskah')} diblokir.`:'Data terkait langsung disembunyikan dari Jejaring.';toast.success('Persetujuan dicabut',`Poin dan tier tetap utuh. ${detail}`);}catch(error){toast.error('Pencabutan gagal',error.message);}finally{sedangConsent='';}}

	function bukaProduk(item=null){produkDisunting=item;formulirProduk={name:item?.name||'',category:item?.category||'',description:item?.description||''};berkasProduk=null;editorProdukTerbuka=true;}
	async function simpanProduk(){const body=new FormData();for(const[key,value]of Object.entries(formulirProduk))body.set(key,String(value));if(berkasProduk)body.set('image',berkasProduk);try{if(produkDisunting)await awardeeProfile.updateProduct(produkDisunting.id,body);else await awardeeProfile.createProduct(body);editorProdukTerbuka=false;toast.success('Etalase diperbarui','Produk tersimpan di PocketBase.');}catch(error){toast.error('Produk gagal disimpan',error.message);}}
	async function hapusProduk(item){if(!confirm(`Hapus produk "${item.name}" dari etalase?`))return;try{await awardeeProfile.deleteProduct(item.id);toast.success('Produk dihapus','Riwayat penghapusan tetap tercatat pada audit profil.');}catch(error){toast.error('Produk gagal dihapus',error.message);}}
</script>

<svelte:head><title>Profil Saya · PFriends</title></svelte:head>

{#if !awardee}
	<EmptyState title="Data Awardee belum termuat" message="Sesi sedang dipulihkan. Bila keadaan ini bertahan, silakan masuk ulang." iconPath={ICONS.user} actionLabel="Ke halaman Masuk" actionHref="/masuk" />
{:else if awardeeProfile.loading && !data}
	<p class="py-12 text-center text-sm text-ink-600">Memuat profil dari PocketBase…</p>
{:else if awardeeProfile.error && !data}
	<EmptyState title="Profil belum dapat dimuat" message={awardeeProfile.error} iconPath={ICONS.refresh} actionLabel="Coba lagi" onAction={()=>awardeeProfile.load()} />
{:else}
	<PageHeader title="Profil Saya" subtitle="Identitas, capaian kontribusi, etalase usaha, dan kendali atas data pribadimu." eyebrow="Open Community Ecosystem" />

	<div class="grid gap-4 lg:grid-cols-3">
		<Card padding="lg" class="lg:col-span-2">
			<div class="mb-4 flex justify-end"><Button variant="outline" size="sm" iconPath={ICONS.edit} onclick={bukaEditorProfil}>Edit profil</Button></div>
			<div class="flex flex-wrap items-start gap-4">
				<Avatar name={awardee.fullName} src={profil?.avatarUrl||''} size="xl" tier={gamification.tier.level} showRing />
				<div class="min-w-0 flex-1"><h2 class="text-lg font-extrabold text-heading">{awardee.fullName}</h2><p class="mt-0.5 text-sm text-ink-600">{profil?.occupation||awardee.communityDef.peran}</p><div class="mt-2 flex flex-wrap gap-2"><StatusBadge label={awardee.communityDef.akronim} color="navy" size="sm"/><StatusBadge label={awardee.chapterDef.label} color="slate" size="sm"/><StatusBadge label={profil?.profileVisibility==='PRIVATE'?'Privat dari Jejaring':'Tampil di Jejaring'} color={profil?.profileVisibility==='PRIVATE'?'slate':'green'} size="sm"/></div></div>
			</div>
			{#if profil?.bio}<p class="mt-4 text-sm leading-relaxed text-ink-700">{profil.bio}</p>{/if}
			<dl class="mt-5 grid gap-3 border-t border-ink-100 pt-4 sm:grid-cols-2"><div><dt class="label-micro">Surel terverifikasi</dt><dd class="mt-0.5 text-sm text-ink-800">{profil?.email||awardee.email}</dd></div><div><dt class="label-micro">WhatsApp</dt><dd class="numeric mt-0.5 text-sm text-ink-800">{profil?.whatsapp||'-'}</dd></div><div><dt class="label-micro">Kota domisili</dt><dd class="mt-0.5 text-sm text-ink-800">{profil?.city||'-'}</dd></div><div><dt class="label-micro">Bergabung</dt><dd class="mt-0.5 text-sm text-ink-800">{formatTanggal(profil?.joinedAt||awardee.joinedAt,'panjang')}</dd></div></dl>
			{#if profil?.skills?.length}<div class="mt-4 border-t border-ink-100 pt-4"><p class="label-micro">Keahlian</p><div class="mt-2 flex flex-wrap gap-1.5">{#each profil.skills as skill (skill)}<StatusBadge label={skill} color="blue" size="sm" variant="outline" />{/each}</div></div>{/if}
		</Card>

		<Card padding="lg"><h2 class="text-sm font-bold text-heading">Tier dan capaian</h2><div class="mt-4"><TierProgress points={gamification.points} tiers={gamification.tiers} showLabels={false}/></div><div class="mt-5 grid grid-cols-2 gap-3 border-t border-ink-100 pt-4"><div><p class="label-micro">Koin Tukar</p><div class="mt-1"><PointsChip points={gamification.coins} currency="KT" size="sm"/></div></div><div><p class="label-micro">Streak harian</p><p class="numeric mt-1 text-sm font-bold">{frasaHitung(gamification.streakDays,'hari')}</p><p class="mt-1 text-xs text-ink-500">{gamification.activeToday?'Poin sah sudah masuk hari ini.':gamification.streakDays>0?'Raih poin hari ini untuk melanjutkan streak.':'Belum ada poin sah hari ini.'}</p></div></div><div class="mt-4 rounded-xl bg-surface-soft p-3"><p class="flex items-center gap-1.5 text-xs font-semibold"><Icon path={poinFiturPublikTerpenuhi?ICONS.checkCircle:ICONS.lock} size={14}/>{poinFiturPublikTerpenuhi?'Ambang fitur publik terpenuhi':`Butuh ${formatAngka(ambangFiturPublik-gamification.points)} poin lagi`}</p></div></Card>
	</div>

	<section class="mt-7"><h2 class="mb-3 text-base font-bold text-heading">Statistik Cerita</h2><div class="grid grid-cols-2 gap-3 lg:grid-cols-4"><StatTile label="Total Cerita" value={statistik.total} hint="Seluruh status" iconPath={ICONS.book}/><StatTile label="Sedang diproses" value={statistik.processing} hint="Diajukan sampai disetujui" iconPath={ICONS.clock}/><StatTile label="Sudah terbit" value={statistik.published} hint="Tayang di kanal publik" iconPath={ICONS.checkCircle}/><StatTile label="Total tayangan" value={statistik.totalViews} hint="Akumulasi dari PocketBase" iconPath={ICONS.eye}/></div></section>

	<section class="mt-8"><div class="mb-3 flex items-baseline justify-between"><h2 class="text-base font-bold">Lencana terkumpul <span class="numeric text-sm text-ink-600">{lencanaTerkumpul.length} dari {gamification.badges.length}</span></h2><a href="/awardee/penghargaan" class="text-sm font-semibold text-brand-700">Buka Pencapaian</a></div>{#if lencanaTerkumpul.length}<ul class="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">{#each lencanaTerkumpul as item (item.badge.code)}<li><BadgeTile badge={item.badge} unlocked/></li>{/each}</ul>{:else}<EmptyState title="Belum ada lencana" message="Lencana akan terbuka ketika kriterianya terpenuhi." iconPath={ICONS.badge} size="sm"/>{/if}</section>

	<section class="mt-8"><h2 class="text-base font-bold">Kontribusi ESG</h2><p class="mb-3 text-sm text-ink-600">Dihitung dari ledger poin terverifikasi di PocketBase.</p><div class="grid gap-3 md:grid-cols-3">{#each ringkasanEsg.rows as row (row.pillar)}<Card padding="md"><div class="flex items-center gap-2"><span class="inline-flex h-8 w-8 items-center justify-center rounded-lg bg-surface-soft font-bold">{row.pillar}</span><div><p class="text-sm font-bold">{row.label}</p><p class="numeric text-xs text-ink-600">{frasaHitung(row.count,'aksi')}</p></div></div></Card>{/each}</div></section>

	{#if awardee.isWomenpreneur}
		<section class="mt-8"><div class="mb-3 flex flex-wrap items-center justify-between gap-2"><div><h2 class="text-base font-bold">Etalase produk</h2><p class="text-sm text-ink-600">Maksimal lima produk. Kontak usaha hanya tampil saat consent data usaha aktif.</p></div><Button size="sm" iconPath={ICONS.plus} disabled={produk.length>=5} onclick={()=>bukaProduk()}>Tambah produk</Button></div>{#if produk.length}<div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{#each produk as item (item.id)}<Card padding="md"><img src={item.imageUrl} alt={item.name} width="640" height="400" class="h-40 w-full rounded-xl object-cover"/><p class="mt-3 text-sm font-bold">{item.name}</p><p class="text-xs font-semibold text-brand-700">{item.category}</p><p class="mt-1 text-xs text-ink-600">{item.description}</p><div class="mt-3 flex gap-2"><Button size="sm" variant="outline" onclick={()=>bukaProduk(item)}>Edit</Button><Button size="sm" variant="ghost" onclick={()=>hapusProduk(item)}>Hapus</Button></div></Card>{/each}</div>{:else}<EmptyState title="Etalase masih kosong" message="Tambahkan foto dan deskripsi produk agar dapat ditemukan Awardee lain di Jejaring." iconPath={ICONS.briefcase} size="sm"/>{/if}</section>
	{/if}

	<section class="mt-8"><h2 class="text-base font-bold">Privasi dan persetujuan</h2><p class="mb-4 text-sm text-ink-600">Setiap perubahan disimpan sebagai rekaman baru di PocketBase. Mencabut persetujuan tidak mengurangi poin maupun tier.</p><div class="grid gap-3 md:grid-cols-2">{#each OPTIONAL_CONSENTS as type (type)}{@const meta=CONSENT_TYPE_META[type]}<Card padding="md"><div class="flex items-start justify-between gap-3"><div><div class="flex flex-wrap items-center gap-2"><p class="text-sm font-bold">{meta.label}</p><StatusBadge label={meta.risiko} color={WARNA_RISIKO[meta.risiko]} size="sm"/><StatusBadge label={consentEffective[type]?'Aktif':'Tidak aktif'} color={consentEffective[type]?'green':'slate'} size="sm"/></div><p class="mt-2 text-xs leading-relaxed text-ink-600">{meta.deskripsi}</p></div>{#if consentEffective[type]}<Button size="sm" variant="outline" loading={sedangConsent===type} onclick={()=>consentDikonfirmasi=type}>Cabut</Button>{:else}<Button size="sm" loading={sedangConsent===type} onclick={()=>aktifkanConsent(type)}>Aktifkan</Button>{/if}</div></Card>{/each}</div>
		<h3 class="mt-6 text-sm font-bold">Riwayat consent</h3><div class="mt-2 space-y-2">{#each consentHistory as item (item.id)}<div class="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-ink-100 p-3"><div><p class="text-sm font-semibold">{CONSENT_TYPE_META[item.consentType]?.label||item.consentType}</p><p class="text-xs text-ink-600">{item.eventType==='GRANTED'?'Diberikan':'Dicabut'} pada {formatTanggal(item.occurredAt,'waktu')} · versi {item.policyVersion}</p></div><StatusBadge label={item.eventType==='GRANTED'?'Diberikan':'Dicabut'} color={item.eventType==='GRANTED'?'green':'slate'} size="sm"/></div>{/each}</div>
	</section>

	<Modal open={editorProfilTerbuka} title="Edit profil" size="lg" onclose={()=>editorProfilTerbuka=false}><div class="grid gap-4 sm:grid-cols-2"><label><span class="label-micro">WhatsApp</span><input bind:value={formulirProfil.whatsapp} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label><span class="label-micro">Kota domisili</span><input bind:value={formulirProfil.city} maxlength="120" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label><span class="label-micro">Pekerjaan atau peran</span><input bind:value={formulirProfil.occupation} maxlength="160" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label><span class="label-micro">Visibilitas</span><select bind:value={formulirProfil.profileVisibility} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"><option value="DIRECTORY">Tampil di Jejaring</option><option value="PRIVATE">Privat</option></select></label><label class="sm:col-span-2"><span class="label-micro">Bio</span><textarea bind:value={formulirProfil.bio} maxlength="1200" rows="3" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"></textarea></label><label class="sm:col-span-2"><span class="label-micro">Keahlian</span><input bind:value={formulirProfil.skills} placeholder="Pisahkan dengan koma" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label class="sm:col-span-2"><span class="label-micro">Foto profil, maksimal 2 MB</span><input type="file" accept="image/jpeg,image/png,image/webp" onchange={(event)=>berkasAvatar=event.currentTarget.files?.[0]||null} class="mt-1.5 block w-full text-sm"/></label><label class="sm:col-span-2 flex items-center gap-2 text-sm"><input type="checkbox" bind:checked={formulirProfil.openToMentoring}/> Bersedia menjadi mentor</label>{#if awardee.isWomenpreneur}<h3 class="sm:col-span-2 border-t border-ink-100 pt-4 text-sm font-bold">Profil usaha</h3><label><span class="label-micro">Nama usaha</span><input bind:value={formulirProfil.businessName} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label><span class="label-micro">Kategori</span><input bind:value={formulirProfil.businessSector} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label><span class="label-micro">Lokasi usaha</span><input bind:value={formulirProfil.businessCity} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label><span class="label-micro">WhatsApp usaha</span><input bind:value={formulirProfil.businessContact} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label class="sm:col-span-2"><span class="label-micro">Deskripsi usaha</span><textarea bind:value={formulirProfil.businessDescription} maxlength="1600" rows="3" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"></textarea></label><label><span class="label-micro">Tenaga kerja</span><input type="number" min="0" bind:value={formulirProfil.businessEmployees} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label><span class="label-micro">Pertumbuhan (%)</span><input type="number" min="-100" bind:value={formulirProfil.businessGrowthPercent} class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label>{/if}</div>{#snippet footer()}<Button variant="ghost" onclick={()=>editorProfilTerbuka=false}>Batal</Button><Button loading={awardeeProfile.working} onclick={simpanProfil}>Simpan profil</Button>{/snippet}</Modal>

	<Modal open={editorProdukTerbuka} title={produkDisunting?'Edit produk':'Tambah produk'} size="md" onclose={()=>editorProdukTerbuka=false}><div class="space-y-4"><label class="block"><span class="label-micro">Nama produk</span><input bind:value={formulirProduk.name} maxlength="160" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label class="block"><span class="label-micro">Kategori</span><input bind:value={formulirProduk.category} maxlength="120" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"/></label><label class="block"><span class="label-micro">Deskripsi</span><textarea bind:value={formulirProduk.description} maxlength="1200" rows="3" class="mt-1.5 w-full rounded-xl border border-ink-300 px-3 py-2 text-sm"></textarea></label><label class="block"><span class="label-micro">Foto produk, maksimal 5 MB {produkDisunting?'(opsional jika tidak diganti)':'(wajib)'}</span><input type="file" accept="image/jpeg,image/png,image/webp" onchange={(event)=>berkasProduk=event.currentTarget.files?.[0]||null} class="mt-1.5 block w-full text-sm"/></label></div>{#snippet footer()}<Button variant="ghost" onclick={()=>editorProdukTerbuka=false}>Batal</Button><Button loading={awardeeProfile.working} onclick={simpanProduk}>Simpan produk</Button>{/snippet}</Modal>

	<Modal open={consentDikonfirmasi!==null} title="Cabut persetujuan ini?" size="sm" onclose={()=>consentDikonfirmasi=null}>{#if consentDikonfirmasi}<p class="text-sm leading-relaxed text-ink-700"><strong>{CONSENT_TYPE_META[consentDikonfirmasi].label}</strong> akan dicatat sebagai dicabut. Poin, tier, dan lencana tetap utuh.</p>{/if}{#snippet footer()}<Button variant="ghost" onclick={()=>consentDikonfirmasi=null}>Batal</Button><Button variant="danger" loading={Boolean(sedangConsent)} onclick={cabutConsent}>Ya, cabut</Button>{/snippet}</Modal>
{/if}
